use Flexgrid\Modules\AdminBanking\Application\Command\CreateBankAccountCommand;use Flexgrid\Modules\AdminBanking\Contract\BankAccountRepositoryInterface;use Flexgrid\Modules\AdminBanking\Domain\Model\BankAccount;use Flexgrid\Modules\AdminCore\Context\TenantContext;use Flexgrid\Modules\AdminCore\Contract\PublicIdGeneratorInterface;use Flexgrid\Modules\AdminCore\Contract\TransactionManagerInterface;use Flexgrid\Modules\AdminCore\ValueObject\Currency;use Flexgrid\Utils\_Time;
final class CreateBankAccount{private$tenant,$ids,$transactions,$accounts,$clock;public function __construct(TenantContext$tenant,PublicIdGeneratorInterface$ids,TransactionManagerInterface$transactions,BankAccountRepositoryInterface$accounts,_Time$clock){$this->tenant=$tenant;$this->ids=$ids;$this->transactions=$transactions;$this->accounts=$accounts;$this->clock=$clock;}public function execute(CreateBankAccountCommand$command):BankAccount{$tenant=$this->tenant->getTenantId();return$this->transactions->transactional(function()use($tenant,$command):BankAccount{$existing=$this->accounts->findByAccountReference($tenant,$command->getAccountReference());if($existing!==null){return$existing;}$account=new BankAccount($this->ids->generate(),$tenant,$command->getName(),$command->getAccountReference(),new Currency($command->getCurrency()),$command->getIban());$this->accounts->insert($account,(int)$this->clock->get());return$account;});}}
